@Component
public class MaterialLibrariesDao extends AbstractDao {
    private static final Logger LOGGER = LoggerFactory.getLogger(MaterialLibrariesDao.class);

    public void insert(List<MaterialLibrariesPO> materialLibrariesPOList) throws ServiceException {
        if (CollectionUtils.isEmpty(materialLibrariesPOList)) {
            return;
        }
        try {
            MaterialLibrariesMapper mapper = getMapper(MaterialLibrariesMapper.class);
            mapper.insert(materialLibrariesPOList);
        } catch (Exception e) {
            LOGGER.error("insert failed. {}", e.getMessage());
            throwServiceException(LOGGER, "insert material");
        }
    }

    public List<MaterialLibrariesPO> selectByConversationId(RetrieveMaterialRequest query) throws ServiceException {
        try {
            MaterialLibrariesMapper mapper = getMapper(MaterialLibrariesMapper.class);
            return mapper.selectByConversationId(query);
        } catch (Exception e) {
            LOGGER.error("selectByConversationId failed. {}", e.getMessage());
            throwServiceException(LOGGER, "select material by conversationId");
        }
        return Collections.emptyList();
    }

    public void deleteByConversationIdAndChatId(String conversationId, String chatId) throws ServiceException {
        if (StringUtils.isEmpty(conversationId)) {
            return;
        }
        try {
            MaterialLibrariesMapper mapper = getMapper(MaterialLibrariesMapper.class);
            mapper.deleteByConversationIdAndChatId(conversationId, chatId);
        } catch (Exception e) {
            LOGGER.error("deleteByConversationIdAndChatId failed. {}", e.getMessage());
            throwServiceException(LOGGER, "delete material by conversationId and chatId");
        }
    }
}
